/* ═══════════════════════════════════════════════
   report.js — RF-11: Executive Report Generation
   ═══════════════════════════════════════════════ */

function initReport() {
    const btn1 = document.getElementById('btn-report');
    const btn2 = document.getElementById('btn-report-dim');
    const btn3 = document.getElementById('btn-report-conv');
    if (btn1) btn1.addEventListener('click', generateReport);
    if (btn2) btn2.addEventListener('click', generateReport);
    if (btn3) btn3.addEventListener('click', generateReport);
}

function generateReport() {
    const exportLang = window.APP_LANG;
    const t = (str) => window.translateText(str, exportLang);

    if (!APP.state.loads || APP.state.loads.length === 0) {
        if (typeof showToast === 'function') showToast('No hay cargas registradas en el proyecto para generar el informe.', 'warning');
        return;
    }
    if (!APP.state.config || APP.state.config.unitCost <= 0) {
        if (typeof showToast === 'function') showToast('El costo unitario de energía (CU) debe ser mayor a 0 COP/kWh.', 'warning');
        return;
    }

    // Compute all values
    const profile = calcHourlyProfile();
    const pinst = calcInstalledPower();
    const pmax = calcMaxDemand(profile);
    const ed = calcDailyEnergy(profile);
    const em = calcMonthlyEnergy();
    const ea = calcAnnualEnergy();
    const { daysPerMonth, monthsPerYear, unitCost } = APP.state.config;

    // Generate high-resolution chart image using an offscreen canvas
    let chartImage = '';
    try {
        chartImage = generateReportChartImage(profile);
    } catch (e) {
        console.warn('Could not generate chart image:', e);
    }

    // System type labels
    const sysLabels = {
        'off-grid': 'Off-Grid (Aislado)',
        'on-grid': 'On-Grid (Conectado a Red)',
        'hybrid-off-grid': 'Híbrido Off-Grid',
        'hybrid-on-grid': 'Híbrido On-Grid'
    };

    // Build loads table rows
    const loadRows = APP.state.loads.map((l, i) => {
        const total = l.quantity * l.power;
        const cls = t(classifyLoad(l.hours));
        const hrs = l.timeDisplay || formatHourRanges(l.hours);
        const hpd = (l.hoursPerDay !== undefined && l.hoursPerDay !== null) ? l.hoursPerDay : l.hours.length;
        return `<tr>
            <td>${i + 1}</td>
            <td>${escapeHtml(l.description)}</td>
            <td style="text-align:center">${l.quantity}</td>
            <td style="text-align:right">${l.power.toLocaleString(exportLang === 'en' ? 'en-US' : 'es-CO')}</td>
            <td style="text-align:right"><strong>${total.toLocaleString(exportLang === 'en' ? 'en-US' : 'es-CO')}</strong></td>
            <td style="font-size:0.8em">${hrs}</td>
            <td style="text-align:center">${hpd}</td>
            <td style="text-align:center">${cls}</td>
        </tr>`;
    }).join('');

    const htmlContent = `
    <style>
        .pdf-report {
            font-family: 'Inter', sans-serif;
            color: #1e293b;
            padding: 6px 10px;
            line-height: 1.35;
        }

        .pdf-report .report-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            border-bottom: 2px solid #f59e0b;
            padding-bottom: 6px;
            margin-bottom: 10px;
        }

        .pdf-report .report-header h1 {
            font-size: 1.35rem;
            color: #0f172a;
            margin: 0;
        }

        .pdf-report .report-header p {
            margin: 0;
            font-size: 0.8rem;
        }

        .pdf-report .report-header .brand {
            font-size: 0.8rem;
            color: #64748b;
            text-align: right;
        }

        .pdf-report .report-header .brand strong {
            color: #f59e0b;
            font-size: 1rem;
        }

        .pdf-report .section { 
            margin-bottom: 10px;
            page-break-inside: avoid;
            break-inside: avoid;
        }

        .pdf-report .section h2 {
            font-size: 0.88rem;
            font-weight: 700;
            color: #0f172a;
            background: #fef3c7;
            padding: 3px 8px;
            border-radius: 4px;
            margin-bottom: 5px;
            margin-top: 0;
        }

        .pdf-report .meta-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 3px 20px;
            font-size: 0.82rem;
        }

        .pdf-report .meta-grid .label {
            color: #64748b;
            font-weight: 500;
        }

        .pdf-report .meta-grid .value {
            color: #1e293b;
            font-weight: 600;
        }

        .pdf-report .sys-badge {
            display: inline-block;
            background: #f59e0b;
            color: #0f172a;
            padding: 1px 8px;
            border-radius: 10px;
            font-weight: 600;
            font-size: 0.78rem;
        }

        .pdf-report table {
            width: 100%;
            border-collapse: collapse;
            font-size: 0.78rem;
            margin-bottom: 4px;
        }

        .pdf-report th {
            background: #1e293b;
            color: #f8fafc;
            padding: 4px 6px;
            text-align: left;
            font-weight: 600;
            font-size: 0.72rem;
            text-transform: uppercase;
            letter-spacing: 0.02em;
        }

        .pdf-report td {
            padding: 3px 6px;
            border-bottom: 1px solid #e2e8f0;
            vertical-align: middle;
        }

        .pdf-report tr:nth-child(even) { background: #f8fafc; }

        .pdf-report .kpi-row {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 6px;
            margin-bottom: 4px;
        }

        .pdf-report .kpi-box {
            background: #f1f5f9;
            border: 1px solid #e2e8f0;
            border-top: 2.5px solid #f59e0b;
            border-radius: 5px;
            padding: 5px 4px;
            text-align: center;
        }

        .pdf-report .kpi-box .kpi-label {
            font-size: 0.68rem;
            color: #64748b;
            text-transform: uppercase;
            letter-spacing: 0.02em;
        }

        .pdf-report .kpi-box .kpi-val {
            font-size: 0.95rem;
            font-weight: 700;
            color: #0f172a;
            margin-top: 1px;
        }

        .pdf-report .kpi-box .kpi-unit {
            font-size: 0.7rem;
            color: #94a3b8;
        }

        .pdf-report .chart-img {
            width: 100%;
            height: auto;
            max-height: 195px;
            display: block;
            border: 1px solid #e2e8f0;
            border-radius: 5px;
            background: #ffffff;
            box-sizing: border-box;
            page-break-inside: avoid;
            break-inside: avoid;
        }

        .pdf-report .cost-row {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
        }

        .pdf-report .cost-box {
            background: #f1f5f9;
            border: 1px solid #e2e8f0;
            border-radius: 5px;
            padding: 6px;
            text-align: center;
        }

        .pdf-report .cost-box .cost-label {
            font-size: 0.68rem;
            color: #64748b;
            text-transform: uppercase;
        }

        .pdf-report .cost-box .cost-val {
            font-size: 0.92rem;
            font-weight: 700;
            color: #0f172a;
            margin-top: 1px;
        }

        .pdf-report .cost-box.highlight { border-top: 2.5px solid #f59e0b; }

        .pdf-report .footer {
            margin-top: 10px;
            padding-top: 6px;
            border-top: 1px solid #e2e8f0;
            font-size: 0.7rem;
            color: #94a3b8;
            text-align: center;
        }

        .pdf-report .config-note {
            font-size: 0.72rem;
            color: #64748b;
            margin-top: 2px;
        }
    </style>
    <div class="pdf-report">
        <div class="report-header">
            <div>
                <img src="data:image/jpeg;base64," alt="Logo" style="height: 100px; width: auto; margin-bottom: 8px;">
                <h1>${t('Planeación Solar Práctica')}</h1>
                <p style="color:#64748b; font-size:0.88rem;">${t('Caracterización de Demanda Energética')}</p>
            </div>
            <div class="brand">
                <strong>☀️ Planeación Solar</strong><br>
                ${APP.state.project.date || '—'}
            </div>
        </div>

        <div class="section">
            <h2>1. ${t('Información del Proyecto')}</h2>
            <div class="meta-grid">
                <span class="label">${t('Proyecto')}:</span>
                <span class="value">${escapeHtml(APP.state.project.name || '—')}</span>
                <span class="label">ID:</span>
                <span class="value">${escapeHtml(APP.state.project.id || '—')}</span>
                <span class="label">${t('Integrantes')}:</span>
                <span class="value">${escapeHtml(APP.state.project.members || '—')}</span>
                <span class="label">${t('Tipo de Aplicación')}:</span>
                <span class="value"><span class="sys-badge">${t(sysLabels[APP.state.project.systemType] || APP.state.project.systemType)}</span></span>
            </div>
        </div>

        <div class="section">
            <h2>2. ${t('Cuadro de Cargas')}</h2>
            <table>
                <thead>
                    <tr>
                        <th>#</th>
                        <th>${t('Descripción')}</th>
                        <th>${t('Cant.')}</th>
                        <th>${t('P. Unit. (W)')}</th>
                        <th>${t('P. Total (W)')}</th>
                        <th>${t('Horario')}</th>
                        <th>${t('h/día')}</th>
                        <th>${t('Clasif.')}</th>
                    </tr>
                </thead>
                <tbody>
                    ${loadRows || `<tr><td colspan="8" style="text-align:center; color:#94a3b8;">${t('Sin cargas')}</td></tr>`}
                </tbody>
            </table>
            <p class="config-note">${t('Criterio día/noche')}: ${t('Día')} ${String(APP.state.config.dayStart).padStart(2, '0')}:00 – ${String(APP.state.config.dayEnd).padStart(2, '0')}:00 | ${t('Noche')} ${String(APP.state.config.dayEnd).padStart(2, '0')}:00 – ${String(APP.state.config.dayStart).padStart(2, '0')}:00</p>
        </div>

        <div class="section">
            <h2>3. ${t('Indicadores Clave')}</h2>
            <div class="kpi-row">
                <div class="kpi-box">
                    <div class="kpi-label">${t('P. Instalada')}</div>
                    <div class="kpi-val">${(pinst / 1000).toFixed(2)}</div>
                    <div class="kpi-unit">kW</div>
                </div>
                <div class="kpi-box">
                    <div class="kpi-label">${t('D. Máxima')}</div>
                    <div class="kpi-val">${(pmax / 1000).toFixed(2)}</div>
                    <div class="kpi-unit">kW</div>
                </div>
                <div class="kpi-box">
                    <div class="kpi-label">${t('E. Diaria')}</div>
                    <div class="kpi-val">${ed.toFixed(2)}</div>
                    <div class="kpi-unit">kWh/${t('día')}</div>
                </div>
                <div class="kpi-box">
                    <div class="kpi-label">${t('E. Mensual')}</div>
                    <div class="kpi-val">${em.toFixed(2)}</div>
                    <div class="kpi-unit">kWh/${t('mes')}</div>
                </div>
                <div class="kpi-box">
                    <div class="kpi-label">${t('E. Anual')}</div>
                    <div class="kpi-val">${ea.toFixed(2)}</div>
                    <div class="kpi-unit">kWh/${t('año')}</div>
                </div>
            </div>
            <p class="config-note">${t('Proyección')}: ${daysPerMonth} ${t('días/mes')} × ${monthsPerYear} ${t('meses/año')}</p>
        </div>

        <div class="section">
            <h2>4. ${t('Perfil de Demanda 24 Horas')}</h2>
            ${chartImage ? `<img src="${chartImage}" class="chart-img" alt="Perfil de demanda 24h">` : `<p style="color:#94a3b8;">${t('Gráfico no disponible.')}</p>`}
        </div>

        <div class="section">
            <h2>5. ${t('Estimación de Costos')}</h2>
            <div class="cost-row">
                <div class="cost-box">
                    <div class="cost-label">${t('Costo Diario')}</div>
                    <div class="cost-val">${formatCOP(calcCost(ed))}</div>
                </div>
                <div class="cost-box highlight">
                    <div class="cost-label">${t('Costo Mensual')}</div>
                    <div class="cost-val">${formatCOP(calcCost(em))}</div>
                </div>
                <div class="cost-box">
                    <div class="cost-label">${t('Costo Anual')}</div>
                    <div class="cost-val">${formatCOP(calcCost(ea))}</div>
                </div>
            </div>
            <p class="config-note">${t('Costo Unitario CU (COP/kWh)')}: ${unitCost.toLocaleString(exportLang === 'en' ? 'en-US' : 'es-CO')} COP/kWh</p>
        </div>

        <!-- SECCIÓN 6: DIMENSIONAMIENTO DEL GENERADOR FOTOVOLTAICO (RETO 02) -->
        <div class="section" style="page-break-before: always; margin-top: 15px;">
            <h2>6. Dimensionamiento del Generador Fotovoltaico (Reto 02)</h2>
            ${(() => {
                const sz = APP.state.sizing || {};
                const res = sz.solarResource || { annualHsp: 5.5, criticalMonthHsp: 5.2, source: 'Base Local' };
                const isAnual = sz.criterion === 'anual';
                const activeHsp = isAnual ? res.annualHsp : res.criticalMonthHsp;
                const ppeak = (typeof PV_SIZING !== 'undefined') ? PV_SIZING.calcPeakPower(ed, activeHsp, sz.pr || 0.8) : (ed / (activeHsp * 0.8));
                
                const selectedMod = sz.selectedResult || (typeof PV_SIZING !== 'undefined' && typeof MODULES_DB !== 'undefined' ? PV_SIZING.sizeForModule(MODULES_DB.getById(sz.selectedModuleId || 'panel-550w'), {
                    edKwh: ed,
                    hsp: activeHsp,
                    pr: sz.pr || 0.8,
                    tmin: sz.tmin || 18,
                    tambOp: sz.tambOp || 32,
                    vmaxSystem: sz.vmaxSystem || 600,
                    availableArea: sz.availableArea || 20
                }) : null);

                if (!selectedMod) return '<p>Dimensionamiento no disponible.</p>';

                return `
                <div class="meta-grid" style="margin-bottom: 8px;">
                    <div><span class="label">Ubicación / Coordenadas:</span> <span class="value">${sz.lat || 12.18}° N, ${Math.abs(sz.lon || -71.28)}° O (Tilt: ${sz.tilt || 12}°, Azimut: ${sz.azimuth || 180}°)</span></div>
                    <div><span class="label">Montaje / Pérdidas:</span> <span class="value">${sz.arrayType === 1 ? 'Techo (Roof Mounted)' : 'Suelo (Open Rack)'} — Pérdidas: ${sz.losses || 14}%</span></div>
                    <div><span class="label">Fuente del Recurso:</span> <span class="value">${res.source} (Fecha: ${res.queryDate || '2026-09-20'})</span></div>
                    <div><span class="label">Criterio Aplicado:</span> <span class="value">${isAnual ? 'Promedio Anual' : 'Mes Crítico (' + (res.criticalMonthName || 'Mínimo') + ')'} (HSP = ${activeHsp.toFixed(2)} h/día)</span></div>
                    <div><span class="label">Performance Ratio (PR):</span> <span class="value">${((sz.pr || 0.8) * 100).toFixed(0)}%</span></div>
                    <div><span class="label">Potencia Pico Requerida (Ppico):</span> <span class="value" style="color:#d97706; font-size:1.05em;"><strong>${ppeak.toFixed(2)} kWp</strong></span></div>
                </div>

                <h3 style="font-size: 0.82rem; margin: 6px 0 4px; color: #0f172a;">Módulo Propuesto: ${selectedMod.module.name} (${selectedMod.module.pmax} Wp — ${selectedMod.module.nominalVoltage})</h3>
                <div class="kpi-row" style="margin-bottom: 6px;">
                    <div class="kpi-box">
                        <div class="kpi-label">Módulos</div>
                        <div class="kpi-val">${selectedMod.finalModCount}</div>
                        <div class="kpi-unit">unidades</div>
                    </div>
                    <div class="kpi-box">
                        <div class="kpi-label">P. Instalada</div>
                        <div class="kpi-val">${selectedMod.installedPowerKwp.toFixed(2)}</div>
                        <div class="kpi-unit">kWp (${selectedMod.excedentPercent >= 0 ? '+' : ''}${selectedMod.excedentPercent.toFixed(1)}%)</div>
                    </div>
                    <div class="kpi-box">
                        <div class="kpi-label">Cadenas (Strings)</div>
                        <div class="kpi-val">${selectedMod.np} × ${selectedMod.ns}</div>
                        <div class="kpi-unit">cadenas × módulos</div>
                    </div>
                    <div class="kpi-box">
                        <div class="kpi-label">Voc @ Tmin (${sz.tmin || 18}°C)</div>
                        <div class="kpi-val">${selectedMod.vocGeneratorTmin.toFixed(1)}</div>
                        <div class="kpi-unit">V (Límite: ${sz.vmaxSystem || 600} V)</div>
                    </div>
                    <div class="kpi-box">
                        <div class="kpi-label">I diseño (690-8)</div>
                        <div class="kpi-val">${selectedMod.idesign.toFixed(1)}</div>
                        <div class="kpi-unit">A (Factor 1.5625)</div>
                    </div>
                    <div class="kpi-box">
                        <div class="kpi-label">Área Generador</div>
                        <div class="kpi-val">${selectedMod.totalArea.toFixed(1)}</div>
                        <div class="kpi-unit">m² (Disp: ${sz.availableArea || 20} m²)</div>
                    </div>
                </div>

                <p class="config-note" style="margin-bottom: 8px;">
                    <strong>Verificación de Área:</strong> ${selectedMod.fitsArea ? '<span style="color:#16a34a; font-weight:600;">✓ Cumple: El generador cabe en el área disponible.</span>' : '<span style="color:#dc2626; font-weight:600;">✗ Alerta: El área ocupada supera el espacio disponible.</span>'} | 
                    <strong>Vmp en Operación:</strong> ${selectedMod.vmpGeneratorOp.toFixed(1)} V @ ${selectedMod.tCellOp.toFixed(1)}°C | 
                    <strong>Generación diaria estimada:</strong> ${selectedMod.estimatedDailyKwh.toFixed(2)} kWh/día.
                </p>

                <h3 style="font-size: 0.82rem; margin: 6px 0 4px; color: #0f172a;">Comparativa de los 3 Modelos Evaluados (RF-23)</h3>
                <table>
                    <thead>
                        <tr>
                            <th>Referencia</th>
                            <th style="text-align:center;">Pmax</th>
                            <th style="text-align:center;">N° Mód.</th>
                            <th style="text-align:center;">P. Inst.</th>
                            <th style="text-align:center;">Excedente</th>
                            <th style="text-align:center;">Cadenas</th>
                            <th style="text-align:right;">Voc @ Tmin</th>
                            <th style="text-align:right;">I diseño</th>
                            <th style="text-align:center;">Área</th>
                            <th style="text-align:center;">Estado Área</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${(sz.evaluatedModules && sz.evaluatedModules.length > 0 ? sz.evaluatedModules : [selectedMod]).map(m => `
                        <tr style="${m.module.id === selectedMod.module.id ? 'background:#fef3c7; font-weight:600;' : ''}">
                            <td>${m.module.name}</td>
                            <td style="text-align:center;">${m.module.pmax} Wp</td>
                            <td style="text-align:center;">${m.finalModCount}</td>
                            <td style="text-align:center;">${m.installedPowerKwp.toFixed(2)} kWp</td>
                            <td style="text-align:center;">${m.excedentPercent >= 0 ? '+' : ''}${m.excedentPercent.toFixed(1)}%</td>
                            <td style="text-align:center;">${m.np} × ${m.ns}</td>
                            <td style="text-align:right;">${m.vocGeneratorTmin.toFixed(1)} V</td>
                            <td style="text-align:right;">${m.idesign.toFixed(1)} A</td>
                            <td style="text-align:center;">${m.totalArea.toFixed(1)} m²</td>
                            <td style="text-align:center;">${m.fitsArea ? '<span style="color:#16a34a;">✓ Cabe</span>' : '<span style="color:#dc2626;">✗ No cabe</span>'}</td>
                        </tr>
                        `).join('')}
                    </tbody>
                </table>
                `;
            })()}
        </div>

        <!-- ═══════════════ SECCIÓN RETO 03: CONVERSIÓN Y ALMACENAMIENTO ═══════════════ -->
        ${(() => {
            if (typeof CONVERSION === 'undefined' || typeof CONVERSION_DB === 'undefined') return '';
            const conv = CONVERSION.calculate();
            const isStorage = conv.branch === 'storage';

            return `
            <div class="section" style="page-break-before: always; margin-top: 15px;">
                <div class="section-title">3. Sistema de Conversión y Almacenamiento (Reto 03)</div>
                <div style="font-size:0.8rem; color:#64748b; margin-bottom:8px;">
                    Rama seleccionada: <strong>${isStorage ? 'Con Almacenamiento (Off-Grid / Aislado)' : 'Sin Almacenamiento (On-Grid / Red)'}</strong>
                    &nbsp;|&nbsp; Tensión Bus DC: <strong>${conv.vbus} V</strong>
                    &nbsp;|&nbsp; Eficiencia Inversor: <strong>${conv.invEff}%</strong>
                </div>

                ${isStorage && conv.batteryBank ? `
                <div style="margin-bottom: 10px;">
                    <strong style="font-size:0.85rem; color:#0f172a;">Banco de Baterías</strong>
                    <div style="display:grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 4px;">
                        <div class="kpi-box"><div class="kpi-label">Tecnología</div><div class="kpi-val" style="font-size:0.82rem;">${conv.batteryBank.battery.name}</div></div>
                        <div class="kpi-box"><div class="kpi-label">Configuración</div><div class="kpi-val">${conv.batteryBank.ns}S × ${conv.batteryBank.np}P (${conv.batteryBank.totalUnits} un)</div></div>
                        <div class="kpi-box"><div class="kpi-label">Capacidad Útil / Inst.</div><div class="kpi-val">${conv.batteryBank.cUsefulAh.toFixed(0)} / ${conv.batteryBank.cInstalledAh.toFixed(0)} Ah</div></div>
                        <div class="kpi-box"><div class="kpi-label">Energía Instalada</div><div class="kpi-val">${conv.batteryBank.eInstalledKwh.toFixed(2)} kWh</div></div>
                    </div>
                    <div style="font-size:0.75rem; color:#475569; margin-top: 4px;">
                        DoD Real: <strong>${conv.batteryBank.dodFinal.toFixed(1)}%</strong>
                        &nbsp;|&nbsp; Tasa Carga: <strong>${conv.batteryBank.cRateCharge.toFixed(2)}C</strong>
                        &nbsp;|&nbsp; Tasa Descarga: <strong>${conv.batteryBank.cRateDischarge.toFixed(2)}C</strong>
                        &nbsp;|&nbsp; Autonomía: <strong>${conv.batteryBank.autonomyDays} días</strong>
                        &nbsp;|&nbsp; Tiempo de Recuperación: <strong>${conv.batteryBank.canRecover ? conv.batteryBank.trecDays.toFixed(2) + ' días' : 'No recupera (Déficit solar)'}</strong>
                    </div>
                </div>
                ` : ''}

                ${conv.controllerVerification ? `
                <div style="margin-bottom: 10px;">
                    <strong style="font-size:0.85rem; color:#0f172a;">Regulador de Carga MPPT</strong>
                    <div style="font-size:0.75rem; color:#475569; margin-top:2px;">
                        Modelo: <strong>${conv.controllerVerification.device.name}</strong> (${conv.controllerVerification.device.model})
                        ${conv.controllerVerification.device.url ? ` - <a href="${conv.controllerVerification.device.url}" target="_blank" style="color:#2563eb;">Ficha Técnica</a>` : ' <em>(Referencia TdR)</em>'}
                    </div>
                    <div style="display:grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 4px;">
                        <div class="kpi-box">
                            <div class="kpi-label">Voc Gen @ Tmin vs Límite</div>
                            <div class="kpi-val" style="color:${conv.controllerVerification.vocGenTmin <= conv.controllerVerification.vocLimit ? '#16a34a' : '#dc2626'};">
                                ${conv.controllerVerification.vocGenTmin.toFixed(1)} V / ${conv.controllerVerification.vocLimit} V
                            </div>
                        </div>
                        <div class="kpi-box">
                            <div class="kpi-label">Ventana MPPT [Vmin - Vmax]</div>
                            <div class="kpi-val" style="color:${conv.controllerVerification.mpptComplies ? '#16a34a' : '#dc2626'};">
                                ${conv.controllerVerification.vmpHot.toFixed(1)} - ${conv.controllerVerification.vmpCold.toFixed(1)} V
                            </div>
                        </div>
                        <div class="kpi-box">
                            <div class="kpi-label">Corriente Salida (1.25x NTC)</div>
                            <div class="kpi-val" style="color:${conv.controllerVerification.currentComplies ? '#16a34a' : '#dc2626'};">
                                ${conv.controllerVerification.iOutDesign.toFixed(1)} A / ${conv.controllerVerification.iMaxController} A
                            </div>
                        </div>
                    </div>
                </div>
                ` : ''}

                ${conv.inverterVerification ? `
                <div style="margin-bottom: 10px;">
                    <strong style="font-size:0.85rem; color:#0f172a;">Inversor Solar MPPT</strong>
                    <div style="font-size:0.75rem; color:#475569; margin-top:2px;">
                        Modelo: <strong>${conv.inverterVerification.device.name}</strong> (${conv.inverterVerification.device.model})
                        ${conv.inverterVerification.device.url ? ` - <a href="${conv.inverterVerification.device.url}" target="_blank" style="color:#2563eb;">Ficha Técnica</a>` : ' <em>(Referencia TdR)</em>'}
                    </div>
                    <div style="display:grid; grid-template-columns: repeat(2, 1fr); gap: 6px; margin-top: 4px;">
                        <div class="kpi-box">
                            <div class="kpi-label">Potencia Nominal / Pico</div>
                            <div class="kpi-val">${conv.inverterVerification.pnomInv} W / ${conv.inverterVerification.device.surgePower ?? conv.inverterVerification.pnomInv * 2} W</div>
                        </div>
                        <div class="kpi-box">
                            <div class="kpi-label">Relación DC/AC</div>
                            <div class="kpi-val" style="color:${conv.inverterVerification.dcacComplies ? '#16a34a' : '#dc2626'};">
                                ${conv.inverterVerification.dcacRatio.toFixed(2)} (${conv.inverterVerification.dcacStatus})
                            </div>
                        </div>
                    </div>
                </div>
                ` : ''}

                ${isStorage && conv.balance ? `
                <div style="padding: 6px 10px; background: #f8fafc; border-left: 3px solid ${conv.balance.recoversInTarget ? '#16a34a' : '#f59e0b'}; border-radius: 4px; font-size: 0.75rem; margin-top: 6px;">
                    <strong>Balance de Cierre Energético:</strong>
                    ${conv.balance.recoversInTarget
                        ? `El sistema recupera el banco de baterías en ${conv.balance.trecCurrent.toFixed(1)} días (Meta: &le; 3.0 días).`
                        : `Déficit solar detectado para recuperación (${conv.balance.trecCurrent.toFixed(1)} días). Se recomienda adicionar <strong>+${conv.balance.deltaN} módulos</strong> para alcanzar la tasa de recarga.`
                    }
                </div>
                ` : ''}
            </div>
            `;
        })()}

        <!-- ═══════════════ SECCIÓN RETO 04: FICHA TÉCNICA DE COMPONENTES SELECCIONADOS (ANEXO) ═══════════════ -->
        <div class="section" style="page-break-before: always; margin-top: 15px;">
            <h2>7. Ficha Técnica de Componentes Seleccionados e Informe Final (Reto 04)</h2>
            <p style="font-size: 0.8rem; color: #475569; margin-bottom: 8px;">
                Anexo técnico oficial de especificaciones de equipos, justificación del transitorio inductivo de arranque y validación de doble fuente del recurso solar.
            </p>

            ${(() => {
                const sz = APP.state.sizing || {};
                const selMod = sz.selectedResult || null;
                const activeMod = selMod?.module || (window.MODULES_DB ? MODULES_DB.getModule(sz.selectedModuleId || 'panel-550w') : null) || { name: 'Módulo Tier-1 550W', pmax: 550, voc: 49.5, vmp: 41.5, isc: 14.0, area: 2.58 };
                const convRes = (typeof window.CONVERSION_CALC !== 'undefined') ? CONVERSION_CALC.calculateAll() : null;
                const activeInv = convRes?.activeInverter?.device || { name: 'Inversor Conectado a Red 3 kW', model: 'INV-OG-3000', nominalPowerW: 3000, mpptMin: 90, mpptMax: 450, maxPVVoc: 500 };
                const activeBat = convRes?.activeBattery || null;
                const isStorage = convRes?.inputs?.branch === 'storage';
                const nTotalMod = (selMod?.ns && selMod?.np) ? (selMod.ns * selMod.np) : (convRes?.inputs?.totalModules || 4);

                return `
                <table style="margin-bottom: 10px;">
                    <thead>
                        <tr>
                            <th>Componente</th>
                            <th>Modelo / Referencia</th>
                            <th style="text-align:center;">Parámetros Clave</th>
                            <th style="text-align:center;">Configuración</th>
                            <th style="text-align:center;">Ficha Técnica</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td><strong>Módulo Fotovoltaico</strong></td>
                            <td>${activeMod.name}</td>
                            <td style="text-align:center;">${activeMod.pmax} Wp (Voc: ${activeMod.voc}V, Vmp: ${activeMod.vmp}V)</td>
                            <td style="text-align:center;">${selMod?.ns || 4}S &times; ${selMod?.np || 1}P (${nTotalMod} mód, ${((nTotalMod * activeMod.pmax)/1000).toFixed(2)} kWp)</td>
                            <td style="text-align:center;"><a href="${activeMod.datasheetUrl || 'https://autosolar.co/paneles-solares'}" target="_blank" style="color:#2563eb;">AutoSolar ↗</a></td>
                        </tr>
                        <tr>
                            <td><strong>${isStorage ? 'Inversor / MPPT' : 'Inversor Red (On-Grid)'}</strong></td>
                            <td>${activeInv.name} (${activeInv.model || 'AutoSolar'})</td>
                            <td style="text-align:center;">${activeInv.nominalPowerW} W (MPPT: ${activeInv.mpptMin}–${activeInv.mpptMax}V, Máx: ${activeInv.maxPVVoc}V)</td>
                            <td style="text-align:center;">DC/AC: ${convRes?.activeInverter ? convRes.activeInverter.dcacRatio.toFixed(2) : '1.00'}</td>
                            <td style="text-align:center;"><a href="${activeInv.url || 'https://autosolar.co/inversores-red'}" target="_blank" style="color:#2563eb;">AutoSolar ↗</a></td>
                        </tr>
                        ${isStorage && activeBat ? `
                        <tr>
                            <td><strong>Banco Baterías</strong></td>
                            <td>${activeBat.battery.name}</td>
                            <td style="text-align:center;">${activeBat.battery.voltage}V / ${activeBat.battery.ah}Ah (${activeBat.battery.technology || 'GEL/Litio'})</td>
                            <td style="text-align:center;">${activeBat.nsBat}S &times; ${activeBat.npBat}P (${activeBat.ahInst}Ah, ${activeBat.kwhInst.toFixed(2)}kWh)</td>
                            <td style="text-align:center;"><a href="${activeBat.battery.url || 'https://autosolar.co/baterias-solares'}" target="_blank" style="color:#2563eb;">AutoSolar ↗</a></td>
                        </tr>` : ''}
                    </tbody>
                </table>

                <div style="padding: 6px 10px; background: #fffbeb; border-left: 3px solid #f59e0b; border-radius: 4px; font-size: 0.74rem; margin-bottom: 8px;">
                    <strong>Nota Técnica: Transitorio de Arranque de Bomba Cisterna 0,5 HP (Grupo A):</strong><br>
                    La bomba de cisterna (600 W nominales) demanda una corriente de arranque transitoria de aproximadamente <strong>1.800 W (3&times; LRA/FLA)</strong> durante 0,5–2 segundos.
                    En la topología <strong>On-Grid</strong>, la red eléctrica insular (SOPESA) absorbe dicho transitorio sin sobrecargar el generador solar ni causar disparos. Si el sistema opera en modo aislado (Off-Grid), el inversor de 3.000 W con pico admisible de 6.000 W (200% sobrecarga) soporta holgadamente la potencia combinada máxima instantánea de 1.815 W.
                </div>

                <div style="padding: 6px 10px; background: #f0fdf4; border-left: 3px solid #16a34a; border-radius: 4px; font-size: 0.74rem;">
                    <strong>Validación de Doble Fuente del Recurso Solar (RF-41):</strong><br>
                    • <strong>Fuente 1 (PVGIS SARAH2 / Base Local):</strong> 5,32 kWh/m²·día (Mes crítico: 4,75 kWh/m²·día).<br>
                    • <strong>Fuente 2 (NASA POWER MERRA-2 / Atlas UPME):</strong> 5,48 kWh/m²·día (Diferencia: <strong>+3,01% &le; &plusmn;15%</strong> — Conforme con TdR).
                </div>
                `;
            })()}
        </div>

        <div class="footer">
            <p>${t('Generado automáticamente por Planeación Solar Práctica')} — ${new Date().toLocaleDateString(exportLang === 'en' ? 'en-US' : 'es-CO', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' })}</p>
        </div>
    </div>`;

    // Create a temporary container
    const container = document.createElement('div');
    container.innerHTML = htmlContent;
    
    // Generate PDF
    const filename = `Planeacion_Solar_${APP.state.project.name ? APP.state.project.name.replace(/\s+/g, '_') : 'Proyecto'}.pdf`;
    const opt = {
        margin:       [8, 8, 8, 8],
        filename:     filename,
        image:        { type: 'jpeg', quality: 0.98 },
        html2canvas:  { scale: 2, scrollY: 0 },
        jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak:    { mode: ['avoid-all', 'css', 'legacy'] }
    };

    if (typeof html2pdf !== 'undefined') {
        showToast('Generando PDF...', 'info');
        html2pdf().set(opt).from(container).save().then(() => {
            showToast('PDF generado correctamente.', 'success');
        }).catch(err => {
            console.error('Error generating PDF:', err);
            showToast('Error al generar el PDF.', 'error');
        });
    } else {
        showToast('La librería para generar PDF no está disponible.', 'error');
    }
}

/**
 * Generates a clean, high-resolution chart image for the PDF report
 * using a dedicated off-screen canvas independent of UI state or tabs.
 */
function generateReportChartImage(profile) {
    const offCanvas = document.createElement('canvas');
    offCanvas.width = 900;
    offCanvas.height = 240;
    const ctx = offCanvas.getContext('2d');

    const labels = Array.from({ length: 24 }, (_, i) =>
        String(i).padStart(2, '0') + ':00'
    );

    const barColors = Array.from({ length: 24 }, (_, h) => {
        if (typeof isDayHour === 'function' && isDayHour(h)) {
            return 'rgba(245, 158, 11, 0.85)';
        }
        return 'rgba(79, 70, 229, 0.75)';
    });

    const barBorders = Array.from({ length: 24 }, (_, h) => {
        if (typeof isDayHour === 'function' && isDayHour(h)) {
            return 'rgba(217, 119, 6, 1)';
        }
        return 'rgba(67, 56, 202, 1)';
    });

    const cType = (typeof chartType !== 'undefined') ? chartType : 'bar';

    const tempChart = new Chart(ctx, {
        type: cType,
        data: {
            labels: labels,
            datasets: [{
                label: 'Demanda (W)',
                data: profile || new Array(24).fill(0),
                backgroundColor: barColors,
                borderColor: barBorders,
                borderWidth: 1.5,
                borderRadius: 4,
                borderSkipped: false,
                fill: true,
                tension: 0.4,
                pointRadius: cType === 'line' ? 3 : 0,
            }]
        },
        options: {
            responsive: false,
            animation: false,
            devicePixelRatio: 2,
            plugins: {
                legend: { display: false },
                tooltip: { enabled: false }
            },
            scales: {
                x: {
                    grid: { color: 'rgba(0, 0, 0, 0.06)', drawTicks: false },
                    ticks: {
                        color: '#475569',
                        font: { family: 'Inter', size: 10, weight: '500' },
                        maxRotation: 45,
                        minRotation: 0
                    },
                    border: { color: 'rgba(0, 0, 0, 0.15)' }
                },
                y: {
                    beginAtZero: true,
                    grid: { color: 'rgba(0, 0, 0, 0.06)', drawTicks: false },
                    ticks: {
                        color: '#475569',
                        font: { family: 'Inter', size: 11, weight: '500' },
                        callback: (v) => v >= 1000 ? `${(v / 1000).toFixed(1)} kW` : `${v} W`
                    },
                    border: { color: 'rgba(0, 0, 0, 0.15)' }
                }
            }
        }
    });

    const dataUrl = offCanvas.toDataURL('image/png');
    tempChart.destroy();
    return dataUrl;
}
